    places: [["Ca'n Joan de S'Aigo", "Old Town", "Ensaimada ve badem dondurması", "Yüzyıllık pastane atmosferinde ada tatlılarını denemek için.", "Ekonomik"], ["Bar España", "Old Town", "Pintxos ve tapas", "Canlı, erişilebilir bir merkez akşamı.", "Orta"], ["Mercat de l'Olivar", "Centro", "Balık ve pazar", "Ada ürünlerini sabah görmek ve kısa öğle yapmak için.", "Orta"], ["Marc Fosh", "Old Town", "Akdeniz fine dining", "Yerel ürünü çağdaş, uzun öğünde deneyimlemek için.", "Yüksek", "Rezervasyon yapın."], ["Fornet de la Soca", "Old Town", "Geleneksel fırın ürünleri", "Yerel tarifleri iyi malzemeyle paket servis almak için.", "Orta"], ["La Rosa Vermutería", "Centro", "Vermut ve paylaşım tabakları", "Pazar–merkez yürüyüşünü rahat bir aperitif ile bitirmek için.", "Orta"]],
